def post_search(request):
    query = request.GET.get("q", "").strip()
    category = request.GET.get("category", "")
    sort = request.GET.get("sort", "newest")
    posts = Post.objects.filter(status="published").select_related("author")
    if query:
        posts = posts.filter(
            Q(title__icontains=query) | Q(body__icontains=query) | Q(author__username__icontains=query)
        )
    if category:
        posts = posts.filter(category__slug=category)
    ordering = {"newest": "-published_at", "oldest": "published_at", "title": "title"}
    posts = posts.order_by(ordering.get(sort, "-published_at"))
    return posts

