from pathlib import Path
from uuid import uuid4

def avatar_path(instance, filename):
    return f"avatars/{instance.user_id}/{uuid4()}{Path(filename).suffix.lower()}"

class Profile(models.Model):
    user = models.OneToOneField(settings.AUTH_USER_MODEL, on_delete=models.CASCADE)
    avatar = models.ImageField(upload_to=avatar_path)

class AvatarForm(forms.ModelForm):
    class Meta:
        model = Profile
        fields = ["avatar"]

    def clean_avatar(self):
        image = self.cleaned_data["avatar"]
        if image.size > 5 * 1024 * 1024:
            raise forms.ValidationError("Maximum size is 5 MB.")
        return image

@login_required
def upload_avatar(request):
    profile, _ = Profile.objects.get_or_create(user=request.user)
    form = AvatarForm(request.POST or None, request.FILES or None, instance=profile)
    if request.method == "POST" and form.is_valid():
        form.save()
        return redirect("profile")
    return render(request, "profile/avatar.html", {"form": form})

