from datetime import timedelta

from django.db import models
from django.utils import timezone

class NoteQuerySet(models.QuerySet):
    def live(self):
        return self.filter(archived_at__isnull=True, purged_at__isnull=True)

class Note(models.Model):
    owner = models.ForeignKey("auth.User", on_delete=models.CASCADE)
    title = models.CharField(max_length=200)
    archived_at = models.DateTimeField(null=True, blank=True)
    purge_after = models.DateField(null=True, blank=True)
    purged_at = models.DateTimeField(null=True, blank=True)
    created_at = models.DateTimeField(auto_now_add=True)

    objects = NoteQuerySet.as_manager()

    class Meta:
        constraints = [
            models.UniqueConstraint(
                fields=["owner", "title"],
                condition=models.Q(archived_at__isnull=True, purged_at__isnull=True),
                name="unique_live_note_title_per_owner",
            ),
        ]

def archive_note(note):
    note.archived_at = timezone.now()
    note.purge_after = timezone.localdate() + timedelta(days=30)
    note.save(update_fields=["archived_at", "purge_after"])
